console.log("SCRIPT CONSULTA CARREGADO");

// ========================
// LOGO EMBUTIDO (BASE64)
// ========================
const LOGO_BASE64 = "data:image/png;base64,";

// ========================
// FORMATA DATA E HORA
// ========================
function formatarDataHora(valor) {
  if (!valor) return "";
  const data = new Date(valor);
  const dia = String(data.getDate()).padStart(2, "0");
  const mes = String(data.getMonth() + 1).padStart(2, "0");
  const ano = data.getFullYear();
  const hora = String(data.getHours()).padStart(2, "0");
  const min = String(data.getMinutes()).padStart(2, "0");
  return `${dia}/${mes}/${ano} - ${hora}:${min}`;
}

// ========================
// GERA TEXTO DO RESUMO
// ========================
function gerarRelatorioConsulta() {
  const nome = document.getElementById("paciente").value.trim();
  const cpf = document.getElementById("cpf").value.trim();
  const rg = document.getElementById("RG").value.trim();
  const inicio = formatarDataHora(document.getElementById("datahoraIni").value);
  const fim = formatarDataHora(document.getElementById("datahoraFin").value);

  const resumo = document.getElementById("resumo");

  // 🔹 separador fixo
  const separador = "\n\nRESUMO DA SESSÃO:\n";

  let relatoUsuario = "";

  // 🔹 se já existe relato digitado, preserva
  if (resumo.value.includes(separador)) {
    relatoUsuario = resumo.value.split(separador)[1];
  }

  // 🔹 monta cabeçalho sempre atualizado
  resumo.value =
`RELATÓRIO DE CONSULTA

Paciente: ${nome}
CPF: ${cpf}
RG: ${rg}

Início da Sessão: ${inicio}
Fim da Sessão: ${fim}
${separador}${relatoUsuario}`;
}
// ========================
// ATUALIZA AUTOMÁTICA
// ========================
document.querySelectorAll("input, textarea").forEach(el => {
  el.addEventListener("input", gerarRelatorioConsulta);
  el.addEventListener("change", gerarRelatorioConsulta);
});

window.addEventListener("DOMContentLoaded", () => {
  gerarRelatorioConsulta();

  const { jsPDF } = window.jspdf;
  const btn = document.getElementById("send-save");

  btn.addEventListener("click", () => {
    const texto = document.getElementById("resumo").value;
    const nome = document.getElementById("paciente").value || "[CONFIDENCIAL]";

    const doc = new jsPDF("p", "mm", "a4");

    // FUNDO
    doc.setFillColor(245, 241, 230);
    doc.rect(0, 0, 210, 297, "F");

    const pageWidth = 210;
    const margin = 15;
    let y = 10;

    // LOGO (SEM ERRO)
    doc.addImage(LOGO_BASE64, "PNG", margin, 12, 18, 18);

    // CABEÇALHO
    doc.setFont("Arial", "bold");
    doc.setFontSize(12);
    doc.text("Dra. Lindsay Salles Báez Salas", pageWidth /2 ,10, {align:"center"});
    y += 25;

    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.text("RP 1921/25", pageWidth /2 ,30, {align:"center"});
    y += 25;
    
    doc.setFont("helvetica","normal");
    doc.setFontSize(8);
    doc.text("Espaço dois Caminhos", margin, 35, {align: "left"});
   y += 25;

    // TÍTULO
    doc.setFontSize(14);
    doc.text(
      "RELATÓRIO DE CONSULTA PSICANALÍTICA",
      pageWidth / 2,
      20,
      { align: "center" }
    );

    // DADOS
    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
    doc.text("DATA: " + new Date().toLocaleDateString(), pageWidth - margin, 40, { align: "right" });
    doc.text(`PACIENTE: ${nome}`, pageWidth - margin, 46, { align: "right" });

    // LINHA
    doc.line(margin, 50, pageWidth - margin, 50);
    y = 60;

    // TEXTO PRINCIPAL
    doc.setFontSize(10);
    const linhas = doc.splitTextToSize(texto, pageWidth - margin * 2);
    doc.text(linhas, margin, y);

    doc.save("relatorio_psicanalitico.pdf");
  });
});
